const items = $input.all();
const today = new Date();
const result = [];

for (const item of items) {
  const d = item.json;

  // Track leads with no email
  if (!d.email) {
    result.push({ json: { ...d, email_tipo: 0, skip_reason: 'sin_email' } });
    continue;
  }

  const estado = (d.estado_email || '').toLowerCase().trim();
  if (estado === 'completado') continue;

  const fecha_c1 = d.fecha_c1 || '';
  const fecha_c2 = d.fecha_c2 || '';
  const fecha_ultima = d.fecha_ultima_interaccion || '';

  let email_tipo = null;

  if (fecha_ultima && estado !== 'reactivado') {
    const dias = (today - new Date(fecha_ultima)) / 86400000;
    if (dias >= 90) { email_tipo = 4; }
  }
  if (!email_tipo && !fecha_c1) { email_tipo = 1; }
  if (!email_tipo && fecha_c1 && !fecha_c2) {
    const dias = (today - new Date(fecha_c1)) / 86400000;
    if (dias >= 3) email_tipo = 2;
  }
  if (!email_tipo && fecha_c2 && !d.fecha_c3) {
    const dias = (today - new Date(fecha_c2)) / 86400000;
    if (dias >= 9) email_tipo = 3;
  }

  if (email_tipo) {
    result.push({ json: { ...d, email_tipo } });
  }
}

return result;

