const items = $input.all();

// Separar clientes de leads por sus columnas características
const clients = items.filter(i =>
  i.json['Cliente/ Notas'] !== undefined ||
  i.json['Cliente/Notas'] !== undefined
);
const leads = items.filter(i =>
  i.json['email'] !== undefined || i.json['nombre'] !== undefined
);

// Set de emails que ya existen en leads
const existing = new Set(
  leads
    .map(l => (l.json.email || '').toString().toLowerCase().trim())
    .filter(e => e.includes('@'))
);

const newClients = [];

for (const c of clients) {
  const nombre = (
    c.json['Cliente/ Notas'] || c.json['Cliente/Notas'] || ''
  ).toString().trim();
  if (!nombre) continue;

  // Puede tener múltiples correos separados por espacios o saltos
  const rawEmails = (c.json['Correos para Cobranza'] || '').toString().trim();
  if (!rawEmails) continue;

  const emails = rawEmails
    .split(/[\s,;\n]+/)
    .map(e => e.trim().toLowerCase())
    .filter(e => e.includes('@'));
  if (emails.length === 0) continue;

  const email = emails[0];
  if (existing.has(email)) continue; // ya está en el sistema

  const direccion = (c.json['Direccion y Telefono'] || '').toString().trim();

  newClients.push({ json: {
    nombre,
    email,
    direccion,
    correo_enviado: '0',
    fecha_c1:       '',
    fecha_c2:       '',
    fecha_c3:       '',
    estado_email:   'reactivar'
  }});
}

if (newClients.length === 0) {
  return [{ json: { _sin_nuevos: true, count: 0 } }];
}

return newClients;

const items = $input.all();
const prepItems = $('✉️ Preparar Email').all();
const allLeads = $('🔍 Clasificar Leads').all();

// Sent emails
const sent = items.map((item, idx) => {
  const lead = (prepItems[idx] || prepItems[0] || {json:{}}).json;
  return {
    empresa: lead.empresa || lead.nombre || '—',
    nombre:  lead.nombre  || lead.empresa || '—',
    email:   lead.email   || '—',
    nicho:   lead.nicho   || '—',
    email_tipo:   String(lead.email_tipo || '—'),
    email_idioma: lead.email_idioma || '—'
  };
});

// Skipped (no email)
const skipped = allLeads
  .filter(l => l.json.skip_reason === 'sin_email')
  .map(l => ({
    nombre:  l.json.nombre  || l.json.empresa || '—',
    empresa: l.json.empresa || l.json.nombre  || '—',
    nicho:   l.json.nicho   || '—'
  }));

return [{ json: { data: sent, skipped } }];
